// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /courses/list').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Ders listesini not ve test istatistikleriyle birleştirir.
const iso = (v) => (v ? new Date(v).toISOString() : null);
const rows = (node) => $(node).all().map((i) => i.json).filter((d) => d && d.id);
const courses = rows('Liste: dersler');
const notes = rows('Liste: notlar');
const attempts = rows('Liste: denemeler');
const latest = (vals) => vals.filter(Boolean).map(iso).sort().pop() || null;

const out = courses.map((c) => {
  const n = notes.filter((x) => x.course_id === c.id);
  const a = attempts.filter((x) => x.course_id === c.id);
  return {
    id: c.id,
    name: c.name,
    note_count: n.length,
    attempt_count: a.length,
    avg_percent: a.length ? Math.round(a.reduce((s, x) => s + Number(x.percent || 0), 0) / a.length) : null,
    last_activity: latest([c.created_at, ...n.map((x) => x.created_at), ...a.map((x) => x.created_at)]),
  };
}).sort((x, y) => x.name.localeCompare(y.name, 'tr'));

return [{ json: { response: { ok: true, data: { courses: out } } } }];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /courses/create').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Ders adını doğrular ve ders belgesini hazırlar.
const crypto = require('crypto');
const b = $('POST /courses/create').first().json.body || {};
const user_id = $('Ekleme: oturum').first().json.user_id;
const name = String(b.name ?? '').trim().replace(/\s+/g, ' ');
if (!name || name.length > 100) {
  return [{ json: { valid: false, response: { ok: false, error: { code: 'VALIDATION_ERROR', message: 'Ders adı 1-100 karakter arasında olmalıdır.' } } } }];
}
const course = { id: crypto.randomUUID(), user_id, name, created_at: new Date().toISOString() };
return [{
  json: {
    valid: true,
    course,
    response: { ok: true, data: { course: { id: course.id, name: course.name, created_at: course.created_at } } },
  },
}];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /courses/update').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Ders adı değiştirme isteğini doğrular.
const b = $('POST /courses/update').first().json.body || {};
const user_id = $('Düzenle: oturum').first().json.user_id;
const s = (v) => (v === null || v === undefined ? '' : String(v).trim());
const course_id = s(b.course_id);
const name = s(b.name).replace(/\s+/g, ' ');
const fail = (message) => [{ json: { valid: false, response: { ok: false, error: { code: 'VALIDATION_ERROR', message } } } }];
if (!course_id) return fail('Ders seçilmelidir.');
if (!name || name.length > 100) return fail('Ders adı 1-100 karakter arasında olmalıdır.');
return [{ json: { valid: true, user_id, course_id, name } }];

// Güncellenecek alanlar ve istemci yanıtı
const v = $('Düzenle: doğrula').first().json;
return [{ json: { id: v.course_id, name: v.name, response: { ok: true, data: { course: { id: v.course_id, name: v.name } } } } }];

// Authorization: Bearer <token> başlığındaki anahtarın SHA-256 özetini çıkarır.
// Veritabanında yalnızca özet saklanır; ham anahtar sadece istemcide bulunur.
const crypto = require('crypto');
const headers = $('POST /courses/delete').first().json.headers || {};
const raw = String(headers.authorization || '').replace(/^Bearer\s+/i, '').trim();
return [{
  json: {
    token_hash: raw ? crypto.createHash('sha256').update(raw).digest('hex') : '-',
    now_ms: Date.now(),
  },
}];

// Silinecek dersin sohbet kimliklerini toplar (mesajlar sohbet üzerinden silinir).
const course = $('Sil: ders').first().json;
const conversation_ids = $('Sil: sohbetler').all().map((i) => i.json.id).filter(Boolean);
return [{ json: { course_id: course.id, user_id: course.user_id, name: course.name, conversation_ids } }];
